 ?><h4><?= e($ppt('Gewählter Kontakt')) ?></h4><dl class="general-settings-description"><?php foreach(['id'=>'Kontaktkennung','name'=>'Name','email'=>'E-Mail','version'=>'Gespeicherte Fassung']as$key=>$label):?><dt><?= e($ppt($label)) ?></dt><dd><?= e($ppv($contact[$key])) ?></dd><?php endforeach ?></dl><details class="general-settings-values" data-assignment-source-values><summary><?= e($ppt('Vollständige Tarifquelle')) ?></summary><p><?= e($catalog['id']) ?> · <?= e($ppt('Gespeicherte Fassung')) ?> <?= e($catalog['version']) ?></p><dl class="general-settings-description"><?php foreach($labels as$key=>$label):$value=$catalog['data'][$key]??'';?><dt><?= e($ppt($label)) ?></dt><dd><?= e($key==='active'?$ppt($value?'Aktiv':'Inaktiv'):(isset($enums[$key][$ppv($value)])?$ppt($enums[$key][$ppv($value)]):$ppv($value))) ?></dd><?php endforeach ?></dl><?php foreach($catalog['data']['tiers']??[]as$row):?><dl class="general-settings-description"><dt><?= e($ppt('Ab Jahren')) ?></dt><dd><?= e($ppv($row['from'])) ?></dd><dt><?= e($ppt('Betrag brutto (EUR)')) ?></dt><dd><?= e($ppv($row['amount'])) ?></dd></dl><?php endforeach ?></details><?php if($source['linked_membership_tariff']):?><p><?= e($ppt('Verknüpfter Einzel- oder Familienjahresbeitrag. Die verbindliche Beitragsforderung bleibt ein eigener Vorgang.')) ?></p><?php endif;
};
$ppData=static function(array $data,bool $raw=false)use($ppt,$ppv,$ppModes):void{?><dl class="general-settings-description"><dt><?= e($ppt('Preisart')) ?></dt><dd><?= e($ppt($ppModes[$ppv($data['mode']??'')]??$ppv($data['mode']??''))) ?></dd><dt><?= e($ppt($raw?'Ursprüngliche Betragseingabe':'Gespeicherter Betrag oder Prozentsatz')) ?></dt><dd><?= e($raw?$ppv($data['value']??''):($data['mode']==='none'?'—':\Kulturhus\Verein\Finance::decimal((int)$data['value_units']))) ?></dd></dl><?php };
$ppSourceFull=static function(array $source)use($ppt,$ppSource):void{?><h4><?= e($ppt('Zugehörige Zuweisung')) ?></h4><dl class="general-settings-description"><?php foreach(['id'=>'Zuweisungskennung','version'=>'Gespeicherte Fassung']as$key=>$label):?><dt><?= e($ppt($label)) ?></dt><dd><?= e($source['assignment'][$key]) ?></dd><?php endforeach;foreach(['start'=>'Beginn','end'=>'Ende']as$key=>$label):?><dt><?= e($ppt($label)) ?></dt><dd><?= e($source['assignment']['data'][$key]===''?$ppt('Offen'):$source['assignment']['data'][$key]) ?></dd><?php endforeach ?></dl><?php $ppSource($source); };
$ppPages=static function(?array $page,string $field)use($ppt,$ppv,$ppUrl,$ppHidden):void{?><form method="get" class="general-settings-page-form"><?= $ppHidden([$field]) ?><label class="general-settings-field"><?= e($ppt('Seite')) ?><input class="form-control" name="<?= e($field) ?>" value="<?= e($ppv($page['page_input']??$_GET[$field]??'1')) ?>" inputmode="numeric"></label><button class="btn btn-outline theme-secondary"><?= e($ppt('Seite öffnen')) ?></button><?php if($page):?><span><?= e($page['total']) ?> · <?= e($page['pages']) ?></span><?php if($page['page']>1):?><a class="btn btn-outline theme-secondary" href="<?= e($ppUrl([$field=>(string)($page['page']-1)])) ?>"><?= e($ppt('Zurück')) ?></a><?php endif;if($page['page']<$page['pages']):?><a class="btn btn-outline theme-secondary" href="<?= e($ppUrl([$field=>(string)($page['page']+1)])) ?>"><?= e($ppt('Weiter')) ?></a><?php endif;endif ?></form><?php };
